"use strict";
Object.assign(labels,{hr:"Хүний нөөц",records:"Бичиг хэрэг",archive:"Архив"});
state.administration={hr:null,records:null,archive:null};
const adminViewModules={hr:"hr",records:"records",archive:"archive"};
Object.assign(viewModules,adminViewModules);
const administrationRenderBefore=render;
render=function(){if(!Object.hasOwn(adminViewModules,state.view))return administrationRenderBefore();renderAdministration(state.view)};
const administrationAdjustBefore=adjustModuleNavigation;
adjustModuleNavigation=function(){administrationAdjustBefore();if(!state.user)return;[["hrNav","hr.manage"],["recordsNav","records.manage"],["archiveNav","archive.manage"]].forEach(([id,permission])=>$("#"+id)?.classList.toggle("hidden",!state.permissions.includes(permission)))};

const administrationStatus={registered:"Бүртгэсэн",assigned:"Хуваарилсан",in_progress:"Шийдвэрлэж буй",responded:"Хариу хүргүүлсэн",closed:"Хаасан",archived:"Архивласан",active:"Идэвхтэй",transferred:"Шилжүүлсэн",due_for_disposal:"Устгах хугацаа болсон",disposed:"Устгасан",incoming:"Ирсэн",outgoing:"Явсан",internal:"Дотоод",low:"Бага",normal:"Хэвийн",high:"Өндөр",urgent:"Яаралтай",public:"Нийтийн",confidential:"Нууц",restricted:"Маш нууц"};
const adminDate=v=>v?String(v).slice(0,10):"—";
const administrationOptions=(items,empty="Сонгохгүй")=>`<option value="">${empty}</option>`+items.map(x=>`<option value="${x.id}">${esc(x.full_name)}</option>`).join("");

async function loadAdministration(view){try{const overview=await api(`/api/${view}/overview`);state.administration[view]=view==="hr"?{...overview,operations:await api("/api/hr/operations")}:overview;if(state.view===view)render()}catch(error){toast(error.message,true)}}
function administrationCards(cards){return `<div class="admin-cards">${cards.map(([label,value,tone=""])=>`<article class="${tone}"><span>${label}</span><strong>${value||0}</strong></article>`).join("")}</div>`}
function renderAdministration(view){const d=state.administration[view];if(!d){$("#pageContent").innerHTML=header("OVERVA",labels[view],"Мэдээллийг ачаалж байна...");queueMicrotask(()=>loadAdministration(view));return}$("#pageContent").innerHTML=view==="hr"?hrAdministration(d):view==="records"?recordsAdministration(d):archiveAdministration(d)}

function hrAdministration(d){const employees=d.employees.map(x=>`<tr><td><strong>${esc(x.full_name)}</strong><small>${esc(x.employee_no||x.username)}</small></td><td>${esc(x.position_title||labels[x.role]||x.role)}<small>${esc(x.department_name||"Хэлтэсгүй")}</small></td><td>${adminDate(x.hire_date)}<small>${esc(x.contract_type||"Гэрээний төрөлгүй")}</small></td><td class="${x.contract_end&&new Date(x.contract_end)<new Date(Date.now()+60*86400000)?"admin-warn":""}">${adminDate(x.contract_end)}</td><td>${x.active?"Идэвхтэй":"Идэвхгүй"}</td></tr>`).join("");const events=d.events.slice(0,12).map(x=>`<li><strong>${esc(x.full_name)} · ${esc(x.title)}</strong><span>${adminDate(x.effective_date)} · ${esc(x.note||"")}</span></li>`).join("");return `${header("ХҮНИЙ НӨӨЦ","Ажилтны бүртгэл ба хөдөлгөөн","Ажилтны хувийн хэрэг, гэрээ болон хөдөлгөөнийг нэг урсгалаар хянана.")}${administrationCards([["Идэвхтэй ажилтан",d.summary.active_employees],["Идэвхгүй",d.summary.inactive_employees],["60 хоногт дуусах гэрээ",d.summary.contracts_expiring,"warn"],["Профайл дутуу",d.summary.incomplete_profiles]])}<div class="admin-two"><form class="admin-form" id="hrProfileForm"><h2>Ажилтны мэдээлэл шинэчлэх</h2><label>Ажилтан<select name="employeeId" required>${administrationOptions(d.employees,"Ажилтан сонгоно уу")}</select></label><div class="admin-fields"><label>Ажилтны дугаар<input name="employeeNo"></label><label>Утас<input name="phone"></label><label>Ажилд орсон<input name="hireDate" type="date"></label><label>Гэрээний төрөл<input name="contractType"></label><label>Гэрээний дугаар<input name="contractNo"></label><label>Гэрээ дуусах<input name="contractEnd" type="date"></label><label>Боловсрол<input name="education"></label><label>Яаралтай холбоо<input name="emergencyContact"></label></div><label>Ажлын байрны тодорхойлолт<textarea name="jobDescription" rows="2"></textarea></label><button class="primary">Профайл хадгалах</button></form><form class="admin-form" id="hrEventForm"><h2>Ажилтны хөдөлгөөн бүртгэх</h2><label>Ажилтан<select name="employeeId" required>${administrationOptions(d.employees,"Ажилтан сонгоно уу")}</select></label><div class="admin-fields"><label>Хөдөлгөөний төрөл<select name="eventType"><option value="hired">Ажилд орсон</option><option value="contract_renewed">Гэрээ сунгасан</option><option value="position_changed">Албан тушаал өөрчлөгдсөн</option><option value="department_changed">Хэлтэс өөрчлөгдсөн</option><option value="leave_started">Чөлөө эхэлсэн</option><option value="leave_ended">Чөлөө дууссан</option><option value="suspended">Түр түдгэлзүүлсэн</option><option value="terminated">Ажлаас чөлөөлсөн</option><option value="note">Бусад тэмдэглэл</option></select></label><label>Хүчин төгөлдөр огноо<input name="effectiveDate" type="date" required></label></div><label>Гарчиг<input name="title" required></label><label>Тайлбар<textarea name="note" rows="3"></textarea></label><button class="secondary">Хөдөлгөөн бүртгэх</button><ul class="admin-events">${events||"<li>Хөдөлгөөн бүртгэгдээгүй.</li>"}</ul></form></div><section class="admin-panel"><div class="panel-head"><h2>Ажилтнууд</h2><span>${d.employees.length} хүн</span></div><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Албан тушаал</th><th>Ажилд орсон / гэрээ</th><th>Гэрээ дуусах</th><th>Төлөв</th></tr></thead><tbody>${employees}</tbody></table></div></section>`}

function recordsAdministration(d){const rows=d.items.map(x=>`<tr><td><strong>${esc(x.registration_no)}</strong><small>${administrationStatus[x.direction]}</small></td><td><strong>${esc(x.subject)}</strong><small>${esc(x.counterparty||"—")} · ${esc(x.document_no||"")}</small></td><td>${adminDate(x.document_date)}</td><td>${esc(x.responsible_name||"—")}</td><td class="${x.due_date&&new Date(x.due_date)<new Date()&&!['closed','archived'].includes(x.status)?"admin-warn":""}">${adminDate(x.due_date)}</td><td><select class="admin-status" data-record-status="${x.id}">${["registered","assigned","in_progress","responded","closed","archived"].map(s=>`<option value="${s}" ${s===x.status?"selected":""}>${administrationStatus[s]}</option>`).join("")}</select></td></tr>`).join("");return `${header("ЗАХИРГАА","Бичиг хэргийн бүртгэл","Ирсэн, явсан болон дотоод албан бичгийг тусдаа дугаарлан шийдвэрлэлтийг хянана.")}${administrationCards([["Нийт бичиг",d.summary.total],["Нээлттэй",d.summary.open],["Хугацаа хэтэрсэн",d.summary.overdue,"warn"],["Энэ сард",d.summary.this_month]])}<form class="admin-form" id="recordsForm"><h2>Шинэ албан бичиг</h2><div class="admin-fields"><label>Урсгал<select name="direction"><option value="incoming">Ирсэн</option><option value="outgoing">Явсан</option><option value="internal">Дотоод</option></select></label><label>Баримтын төрөл<input name="documentType" value="Албан бичиг" required></label><label>Баримтын дугаар<input name="documentNo"></label><label>Баримтын огноо<input name="documentDate" type="date" required></label><label>Харилцагч байгууллага/иргэн<input name="counterparty"></label><label>Хариуцагч<select name="responsibleUserId">${administrationOptions(state.assignableUsers)}</select></label><label>Яаралтай байдал<select name="priority"><option value="normal">Хэвийн</option><option value="high">Өндөр</option><option value="urgent">Яаралтай</option><option value="low">Бага</option></select></label><label>Шийдвэрлэх хугацаа<input name="dueDate" type="date"></label></div><label>Товч утга<input name="subject" required maxlength="500"></label><button class="primary">Бичиг бүртгэх</button></form><section class="admin-panel"><div class="panel-head"><h2>Албан бичгийн жагсаалт</h2><span>${d.items.length} бүртгэл</span></div><div class="admin-table-wrap"><table><thead><tr><th>Бүртгэлийн №</th><th>Товч утга</th><th>Огноо</th><th>Хариуцагч</th><th>Хугацаа</th><th>Төлөв</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Албан бичиг бүртгэгдээгүй байна.</td></tr>'}</tbody></table></div></section>`}

function archiveAdministration(d){const rows=d.items.map(x=>`<tr><td><strong>${esc(x.archive_no)}</strong><small>${esc(x.category)}</small></td><td><strong>${esc(x.title)}</strong><small>${esc(x.document_no||"")} ${x.source_registration_no?`· ${esc(x.source_registration_no)}`:""}</small></td><td>${adminDate(x.archived_at)}</td><td>${esc(x.location||"—")}<small>${esc(x.box_no||"—")} / ${esc(x.shelf_no||"—")}</small></td><td>${x.permanent?"Байнга":`${x.retention_years||0} жил`}</td><td><select class="admin-status" data-archive-status="${x.id}">${["active","transferred","due_for_disposal","disposed"].map(s=>`<option value="${s}" ${s===x.status?"selected":""}>${administrationStatus[s]}</option>`).join("")}</select></td></tr>`).join("");return `${header("БАРИМТЫН УДИРДЛАГА","Архив","Хадгаламжийн нэгжийн байршил, нууцлал болон хадгалах хугацааг хянана.")}${administrationCards([["Нийт баримт",d.summary.total],["Идэвхтэй",d.summary.active],["Байнга хадгалах",d.summary.permanent],["Хугацаа болсон",d.summary.retention_due,"warn"]])}<form class="admin-form" id="archiveForm"><h2>Архивын баримт бүртгэх</h2><div class="admin-fields"><label>Баримтын нэр<input name="title" required></label><label>Ангилал<select name="category"><option>Хүний нөөц</option><option>Захиргаа</option><option>Санхүү</option><option>Бичиг захидал</option><option>Тушаал / Шийдвэр</option><option>Гэрээ</option><option>Техник</option><option>Бусад</option></select></label><label>Баримтын төрөл<input name="documentType"></label><label>Баримтын дугаар<input name="documentNo"></label><label>Баримтын огноо<input name="documentDate" type="date"></label><label>Архивласан огноо<input name="archivedAt" type="date"></label><label>Хадгалах жил<input name="retentionYears" type="number" min="1" max="100" value="10"></label><label class="admin-check"><input name="permanent" type="checkbox"> Байнга хадгалах</label><label>Байршил<input name="location" placeholder="Архивын өрөө"></label><label>Хайрцаг №<input name="boxNo"></label><label>Тавиур №<input name="shelfNo"></label><label>Нууцлал<select name="confidentiality"><option value="internal">Дотоод</option><option value="public">Нийтийн</option><option value="confidential">Нууц</option><option value="restricted">Маш нууц</option></select></label></div><label>Тайлбар<textarea name="description" rows="2"></textarea></label><button class="primary">Архивт бүртгэх</button></form><section class="admin-panel"><div class="panel-head"><h2>Архивын бүртгэл</h2><span>${d.items.length} хадгаламжийн нэгж</span></div><div class="admin-table-wrap"><table><thead><tr><th>Архивын №</th><th>Баримт</th><th>Архивласан</th><th>Байршил / хайрцаг</th><th>Хугацаа</th><th>Төлөв</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Архивын баримт бүртгэгдээгүй байна.</td></tr>'}</tbody></table></div></section>`}

async function reloadAdministration(view,message){state.administration[view]=null;await loadAdministration(view);if(message)toast(message)}
document.addEventListener("submit",async event=>{const form=event.target;if(!["hrProfileForm","hrEventForm","recordsForm","archiveForm"].includes(form.id))return;event.preventDefault();const data=new FormData(form),v=Object.fromEntries(data);try{if(form.id==="hrProfileForm"){const id=v.employeeId;delete v.employeeId;Object.keys(v).forEach(k=>{if(v[k]==="")delete v[k]});await api(`/api/hr/employees/${id}`,{method:"PATCH",body:JSON.stringify(v)});await reloadAdministration("hr","Ажилтны профайл хадгалагдлаа")}if(form.id==="hrEventForm"){const id=v.employeeId;delete v.employeeId;await api(`/api/hr/employees/${id}/events`,{method:"POST",body:JSON.stringify(v)});form.reset();await reloadAdministration("hr","Ажилтны хөдөлгөөн бүртгэгдлээ")}if(form.id==="recordsForm"){v.responsibleUserId=v.responsibleUserId||null;v.dueDate=v.dueDate||null;await api("/api/records",{method:"POST",body:JSON.stringify(v)});form.reset();await reloadAdministration("records","Албан бичиг бүртгэгдлээ")}if(form.id==="archiveForm"){v.permanent=data.has("permanent");v.retentionYears=v.permanent?null:Number(v.retentionYears||10);v.documentDate=v.documentDate||null;await api("/api/archive",{method:"POST",body:JSON.stringify(v)});form.reset();await reloadAdministration("archive","Архивын баримт бүртгэгдлээ")}}catch(error){toast(error.message,true)}});
document.addEventListener("change",async event=>{const record=event.target.closest("[data-record-status]"),archive=event.target.closest("[data-archive-status]");if(!record&&!archive)return;try{if(record){await api(`/api/records/${record.dataset.recordStatus}`,{method:"PATCH",body:JSON.stringify({status:record.value})});await reloadAdministration("records","Бичгийн төлөв шинэчлэгдлээ")}if(archive){await api(`/api/archive/${archive.dataset.archiveStatus}`,{method:"PATCH",body:JSON.stringify({status:archive.value})});await reloadAdministration("archive","Архивын төлөв шинэчлэгдлээ")}}catch(error){toast(error.message,true)}});

// OVERVA HR registry uses the canonical employee record. A login account remains optional.
state.hrRegistry={search:"",department:"",status:"",selectedId:null,file:null,attachments:[],tab:"employees",imports:null,importJob:null};
const hrMoney=value=>value!==null&&value!==undefined&&value!==""?`₮ ${Number(value).toLocaleString("mn-MN",{maximumFractionDigits:0})}`:"—";
const hrValue=value=>value===null||value===undefined?"":String(value);
const hrOption=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current||"")?"selected":""}>${esc(label)}</option>`;
const hrNamedOptions=(items,current,labelKey)=>`<option value="">Сонгохгүй</option>`+items.map(item=>hrOption(item.id,item[labelKey],current)).join("");

const hrLifecycleNames={candidate:"Горилогч",offered:"Ажлын санал хүргэсэн",onboarding:"Ажилд авах шат",active:"Идэвхтэй",on_leave:"Чөлөөтэй",suspended:"Түр түдгэлзсэн",terminated:"Ажлаас гарсан",retired:"Тэтгэвэрт гарсан"};
const hrContractNames={draft:"Ноорог",active:"Идэвхтэй",expired:"Хугацаа дууссан",terminated:"Цуцлагдсан",superseded:"Шинэ хувилбараар солигдсон"};
const hrLines=value=>String(value||"").split("\n").map(x=>x.trim()).filter(Boolean);
function hrHistoryRows(items,renderer,empty){return items.length?items.map(renderer).join(""):`<tr><td colspan="5" class="hr-empty">${empty}</td></tr>`}
function hrLifecycleEditor(employee,file){
  const attached=state.hrRegistry.attachments||[];
  if(!file)return `<section><h3>Хөдөлмөрийн хувийн хэрэг</h3><p class="hr-help">Түүхэн бүртгэлийг ачаалж байна...</p></section>`;
  const contracts=hrHistoryRows(file.contracts,x=>`<tr><td>${esc(x.contract_no)}</td><td>v${x.version_no}</td><td>${esc(x.contract_type)}</td><td>${adminDate(x.starts_on)} – ${adminDate(x.ends_on)}</td><td>${esc(hrContractNames[x.status]||x.status)}</td></tr>`,"Гэрээний түүх алга.");
  const compensation=hrHistoryRows(file.compensation,x=>`<tr><td>${adminDate(x.effective_from)}</td><td>${adminDate(x.effective_to)}</td><td>${esc(x.currency)} ${Number(x.base_salary).toLocaleString("mn-MN")}</td><td>${esc(x.reason||"—")}</td><td>${x.approved_by?"Баталсан":"Батлаагүй"}</td></tr>`,"Цалингийн түүх алга.");
  const lifecycle=hrHistoryRows(file.lifecycle,x=>`<tr><td>${adminDate(x.effective_date)}</td><td>${esc(hrLifecycleNames[x.status]||x.status)}</td><td colspan="3">${esc(x.reason||"—")}</td></tr>`,"Хөдөлмөрийн төлөвийн түүх алга.");
  const documents=hrHistoryRows(file.documents,x=>`<tr><td>${esc(x.document_no)}</td><td>${esc(x.title)}</td><td>${esc(x.document_type)}</td><td>${esc(x.classification_code)}</td><td>${esc(x.status)}</td></tr>`,"Хувийн хэргийн баримт алга.");
  const descriptions=hrHistoryRows(file.positionDescriptions,x=>`<tr><td>v${x.version_no}</td><td>${esc(x.title)}</td><td>${adminDate(x.effective_from)}</td><td>${esc(x.status)}</td><td>${esc(x.purpose||"—")}</td></tr>`,"Албан тушаалын тодорхойлолтын хувилбар алга.");
  return `<section class="hr-lifecycle"><h3>Хөдөлмөрийн хувийн хэрэг · түүхэн бүртгэл</h3><p class="hr-help">Өмнөх мөрийг засахгүй. Өөрчлөлт бүр шинэ хувилбар эсвэл шинэ түүхэн үйл явдал болж хадгалагдана.</p>
    <details open><summary>Гэрээний хувилбарууд (${file.contracts.length})</summary><div class="admin-table-wrap"><table><thead><tr><th>Дугаар</th><th>Хувилбар</th><th>Төрөл</th><th>Хугацаа</th><th>Төлөв</th></tr></thead><tbody>${contracts}</tbody></table></div>
      <form id="hrContractForm" data-employee-id="${employee.id}" class="admin-form"><div class="hr-form-grid"><label>Гэрээний дугаар<input name="contractNo" required></label><label>Гэрээний төрөл<input name="contractType" required></label><label>Эхлэх<input type="date" name="startsOn" required></label><label>Дуусах<input type="date" name="endsOn"></label><label>Төлөв<select name="status">${Object.entries(hrContractNames).map(([k,v])=>hrOption(k,v,"active")).join("")}</select></label><label>Өмнөх contract key<input name="contractKey" placeholder="Зөвхөн шинэ хувилбар бол"></label><label class="span-2">Нөхцөлийн товч<textarea name="termsSummary"></textarea></label></div><button class="secondary">Гэрээний хувилбар нэмэх</button></form></details>
    <details><summary>Цалин, хөлсний түүх (${file.compensation.length})</summary><div class="admin-table-wrap"><table><thead><tr><th>Эхлэх</th><th>Дуусах</th><th>Үндсэн цалин</th><th>Шалтгаан</th><th>Баталгаа</th></tr></thead><tbody>${compensation}</tbody></table></div>
      <form id="hrCompensationForm" data-employee-id="${employee.id}" class="admin-form"><div class="hr-form-grid"><label>Хүчинтэй эхлэх<input type="date" name="effectiveFrom" required></label><label>Хүчинтэй дуусах<input type="date" name="effectiveTo"></label><label>Валют<input name="currency" value="MNT" maxlength="3" required></label><label>Үндсэн цалин<input type="number" name="baseSalary" min="0" required></label><label class="span-2">Өөрчлөлтийн шалтгаан<input name="reason"></label><label class="admin-check"><input type="checkbox" name="approved" value="true"> Баталсан бүртгэл</label></div><button class="secondary">Цалингийн түүх нэмэх</button></form></details>
    <details><summary>Ажил эрхлэлтийн төлөв (${file.lifecycle.length})</summary><div class="admin-table-wrap"><table><thead><tr><th>Огноо</th><th>Төлөв</th><th colspan="3">Шалтгаан</th></tr></thead><tbody>${lifecycle}</tbody></table></div>
      <form id="hrLifecycleForm" data-employee-id="${employee.id}" class="admin-form"><div class="hr-form-grid"><label>Шинэ төлөв<select name="status">${Object.entries(hrLifecycleNames).map(([k,v])=>hrOption(k,v,"")).join("")}</select></label><label>Хүчинтэй огноо<input type="date" name="effectiveDate" required></label><label class="span-2">Шалтгаан<input name="reason"></label></div><button class="secondary">Төлөвийн түүх нэмэх</button></form></details>
    <details><summary>Хувийн хэргийн баримт (${file.documents.length})</summary><div class="admin-table-wrap"><table><thead><tr><th>Дугаар</th><th>Нэр</th><th>Төрөл</th><th>Нууцлал</th><th>Төлөв</th></tr></thead><tbody>${documents}</tbody></table></div>
      <form id="hrDocumentForm" data-employee-id="${employee.id}" class="admin-form"><div class="hr-form-grid"><label>Баримтын дугаар<input name="documentNo" required></label><label>Баримтын нэр<input name="title" required></label><label>Төрөл<input name="documentType" value="employee_file" required></label><label>Нууцлал<select name="classification"><option value="confidential">Нууц</option><option value="restricted">Онцгой хамгаалалттай</option><option value="internal">Дотоод</option></select></label><label>Хадгалалтын ангилал<input name="retentionClass" value="employment_plus_10_years"></label></div><button class="secondary">Баримтын бүртгэл үүсгэх</button></form></details>
    <details><summary>Албан тушаалын тодорхойлолт (${file.positionDescriptions.length})</summary><div class="admin-table-wrap"><table><thead><tr><th>Хувилбар</th><th>Нэр</th><th>Огноо</th><th>Төлөв</th><th>Зорилго</th></tr></thead><tbody>${descriptions}</tbody></table></div>
      ${employee.position_id?`<form id="hrPositionDescriptionForm" data-position-id="${employee.position_id}" data-employee-id="${employee.id}" class="admin-form"><div class="hr-form-grid"><label>Нэр<input name="title" value="${esc(employee.position_title||"")}" required></label><label>Хүчинтэй эхлэх<input type="date" name="effectiveFrom" required></label><label>Төлөв<select name="status"><option value="draft">Ноорог</option><option value="approved">Баталсан</option><option value="retired">Хэрэглэхгүй</option></select></label><label class="span-2">Зорилго<textarea name="purpose"></textarea></label><label>Үндсэн ажил (мөр бүрээр)<textarea name="duties"></textarea></label><label>Хариуцлага (мөр бүрээр)<textarea name="responsibilities"></textarea></label><label>Шаардлага (мөр бүрээр)<textarea name="requirements"></textarea></label></div><button class="secondary">Тодорхойлолтын хувилбар нэмэх</button></form>`:`<p class="hr-help">Эхлээд ажилтанд албан тушаал онооно уу.</p>`}</details>
    <details><summary>Файл хавсралт (${attached.length})</summary><div class="admin-table-wrap"><table><thead><tr><th>Файл</th><th>Төрөл</th><th>Хэмжээ</th><th>Огноо</th><th></th></tr></thead><tbody>${attached.map(x=>`<tr><td>${esc(x.original_name)}</td><td>${esc(x.mime_type)}</td><td>${Math.ceil(Number(x.size_bytes)/1024)} KB</td><td>${adminDate(x.created_at)}</td><td><button type="button" class="hr-edit" data-hr-file-download="${x.id}">Татах</button></td></tr>`).join("")||'<tr><td colspan="5">Файл хавсаргаагүй.</td></tr>'}</tbody></table></div><form id="hrAttachmentForm" data-employee-id="${employee.id}" class="admin-form"><label>Хувийн хэргийн файл (PDF, зураг, Word, Excel · 10 MB хүртэл)<input type="file" name="file" required></label><button class="secondary">Файл хавсаргах</button></form><p class="hr-help">Хувийн хэргийн хавсралтыг түүх хадгалах бодлогын дагуу шууд устгахгүй.</p></details>
  </section>`;
}

function hrEmployeeDialog(d,employee){
  const edit=Boolean(employee),v=employee||{};
  return `<dialog class="hr-dialog" id="hrEmployeeDialog"><form method="dialog" class="hr-dialog-head"><div><small>ХҮНИЙ НӨӨЦИЙН БҮРТГЭЛ</small><h2>${edit?"Ажилтны мэдээлэл":"Шинэ ажилтан"}</h2></div><button value="cancel" aria-label="Хаах">×</button></form>
  <form id="hrEmployeeForm" class="hr-dialog-body" data-employee-id="${esc(v.id||"")}">
    <section><h3>Үндсэн мэдээлэл</h3><div class="hr-form-grid">
      <label>Овог нэр<input name="fullName" value="${esc(hrValue(v.full_name))}" ${edit?"disabled":"required"}></label>
      <label>Ажилтны дугаар<input name="employeeNo" value="${esc(hrValue(v.employee_no))}"></label>
      <label>Регистрийн дугаар<input name="registerNo" value="${esc(hrValue(v.register_no))}"></label>
      <label>Хүйс<select name="gender">${hrOption("","Сонгохгүй",v.gender)}${["Эрэгтэй","Эмэгтэй","Бусад"].map(x=>hrOption(x,x,v.gender)).join("")}</select></label>
      <label>Төрсөн огноо<input type="date" name="birthdate" value="${esc(adminDate(v.birthdate)==="—"?"":adminDate(v.birthdate))}"></label>
      <label>Иргэншил<input name="nationality" value="${esc(hrValue(v.nationality))}"></label>
      <label>Хувийн и-мэйл<input type="email" name="personalEmail" value="${esc(hrValue(v.personal_email))}"></label>
      <label>Утас<input name="phone" value="${esc(hrValue(v.phone))}"></label>
      <label class="span-2">Хаяг<input name="address" value="${esc(hrValue(v.address))}"></label>
    </div></section>
    ${edit?"":`<section><h3>Байгууллагын бүтэц</h3><div class="hr-form-grid"><label>Хэлтэс<select name="departmentId">${hrNamedOptions(d.departments,v.department_id,"name")}</select></label><label>Албан тушаал<select name="positionId">${hrNamedOptions(d.positions,v.position_id,"title")}</select></label><label>Ажлын ангилал<input name="jobRole" value="worker" required></label></div><p class="hr-help">Ажилтан бүртгэгдэнэ. Нэвтрэх эрх автоматаар үүсэхгүй.</p></section>`}
    <section><h3>Ажил эрхлэлт ба гэрээ</h3><div class="hr-form-grid">
      <label>Ажилд орсон<input type="date" name="hireDate" value="${esc(adminDate(v.hire_date)==="—"?"":adminDate(v.hire_date))}"></label>
      <label>Ажлын нөхцөл<input name="workCondition" value="${esc(hrValue(v.work_condition))}"></label>
      <label>Ажилтны төлөв<input name="statusHr" value="${esc(hrValue(v.status_hr||"Идэвхтэй"))}"></label>
      <label>Гэрээний төрөл<input name="contractType" value="${esc(hrValue(v.contract_type))}"></label>
      <label>Гэрээний дугаар<input name="contractNo" value="${esc(hrValue(v.contract_no))}"></label>
      <label>Гэрээ байгуулсан<input type="date" name="contractDate" value="${esc(adminDate(v.contract_date)==="—"?"":adminDate(v.contract_date))}"></label>
      <label>Гэрээ дуусах<input type="date" name="contractEnd" value="${esc(adminDate(v.contract_end)==="—"?"":adminDate(v.contract_end))}"></label>
      <label>Ажилласан жил<input type="number" step="0.1" min="0" name="tenureYears" value="${esc(hrValue(v.tenure_years))}"></label>
      <label>Үндсэн цалин<input type="number" step="1" min="0" name="salary" value="${esc(hrValue(v.salary))}"></label>
    </div></section>
    <section><h3>Мэргэжил ба холбоо</h3><div class="hr-form-grid">
      <label>Боловсрол<input name="education" value="${esc(hrValue(v.education))}"></label>
      <label>Диплом<input name="diploma" value="${esc(hrValue(v.diploma))}"></label>
      <label>Мэргэжлийн үнэмлэх<input name="professionalCert" value="${esc(hrValue(v.professional_cert))}"></label>
      <label>Яаралтай холбоо<input name="emergencyContact" value="${esc(hrValue(v.emergency_contact))}"></label>
      <label>Гэр бүлийн байдал<input name="familyStatus" value="${esc(hrValue(v.family_status))}"></label>
      <label class="span-2">Ажлын байрны тодорхойлолт<textarea name="jobDescription" rows="3">${esc(hrValue(v.job_description))}</textarea></label>
    </div></section>
    <div class="hr-dialog-actions"><button type="button" class="secondary" data-hr-close>Болих</button><button class="primary">${edit?"Мэдээлэл хадгалах":"Ажилтан бүртгэх"}</button></div>
  </form>
  ${edit?hrLifecycleEditor(v,state.hrRegistry.file):""}
  </dialog>`;
}

hrAdministration=function(d){
  const ui=state.hrRegistry;
  const search=ui.search.trim().toLocaleLowerCase("mn-MN");
  const filtered=d.employees.filter(x=>{
    const hay=[x.full_name,x.employee_no,x.personal_email,x.email,x.position_title,x.department_name].filter(Boolean).join(" ").toLocaleLowerCase("mn-MN");
    const status=x.active?(x.status_hr||"Идэвхтэй"):"Идэвхгүй";
    return (!search||hay.includes(search))&&(!ui.department||x.department_name===ui.department)&&(!ui.status||status===ui.status);
  });
  const rows=filtered.map(x=>`<tr>
    <td><div class="hr-person"><span>${esc((x.full_name||"?").trim().slice(0,1).toUpperCase())}</span><div><strong>${esc(x.full_name)}</strong><small>${esc(x.position_title||x.role||"Албан тушаалгүй")} · ${esc(x.personal_email||x.email||x.employee_no||"—")}</small></div></div></td>
    <td><span class="hr-tag">${esc(smartImportDisplayValue(x.department_name)||"Хэлтэсгүй")}</span></td><td>${esc(x.gender||"—")}</td><td>${esc(x.work_condition||"—")}</td>
    <td>${esc(x.education||"—")}</td><td><span class="hr-tag neutral">${esc(smartImportDisplayValue(x.contract_type)||"Тодорхойгүй")}</span><small>${adminDate(x.contract_end)}</small></td>
    <td>${x.tenure_years!==null&&x.tenure_years!==undefined?`${esc(x.tenure_years)} жил`:"—"}</td><td class="hr-money">${hrMoney(x.salary)}</td>
    <td><span class="hr-status ${x.active?"active":"inactive"}">${esc(x.active?(x.status_hr||"Идэвхтэй"):"Идэвхгүй")}</span></td>
    <td><button class="hr-edit" data-hr-edit="${x.id}">Засах</button></td></tr>`).join("");
  const selected=d.employees.find(x=>x.id===ui.selectedId);
  const departments=[...new Set(d.employees.map(x=>x.department_name).filter(Boolean))].sort();
  const statuses=[...new Set(d.employees.map(x=>x.active?(x.status_hr||"Идэвхтэй"):"Идэвхгүй"))].sort();
  return `${header("ХҮНИЙ НӨӨЦИЙН УДИРДЛАГА","Хүний нөөцийн удирдлага","Ажилтны нэгдсэн бүртгэл, хөдөлмөрийн мэдээлэл болон гэрээний хяналт.")}
  <div class="hr-title-actions"><div></div><button class="primary" data-hr-add>+ Ажилтан нэмэх</button></div>
  <div class="admin-cards hr-summary"><article><span>Нийт ажилтан</span><strong>${d.summary.total_employees||0}</strong></article><article class="success"><span>Идэвхтэй</span><strong>${d.summary.active_employees||0}</strong></article><article class="leave"><span>Амралт / өвчтэй</span><strong>${d.summary.on_leave||0}</strong></article><article class="warn"><span>30 хоногт дуусах гэрээ</span><strong>${d.summary.contracts_expiring||0}</strong></article></div>
  <section class="admin-panel hr-registry"><div class="panel-head"><div><h2>Ажилтнууд</h2><span>Ажилтны үндсэн бүртгэл · нэвтрэх бүртгэлээс тусдаа</span></div></div>
    <div class="hr-toolbar"><input data-hr-search placeholder="Нэр, и-мэйл, албан тушаал хайх..." value="${esc(ui.search)}"><select data-hr-department><option value="">Бүх хэлтэс</option>${departments.map(x=>hrOption(x,smartImportDisplayValue(x),ui.department)).join("")}</select><select data-hr-status><option value="">Бүх төлөв</option>${statuses.map(x=>hrOption(x,x,ui.status)).join("")}</select><span>${filtered.length} / ${d.employees.length}</span></div>
    <div class="admin-table-wrap"><table class="hr-table"><thead><tr><th>Ажилтан</th><th>Хэлтэс</th><th>Хүйс</th><th>Ажлын нөхцөл</th><th>Боловсрол</th><th>Гэрээ</th><th>Ажилласан</th><th>Цалин</th><th>Төлөв</th><th>Үйлдэл</th></tr></thead><tbody>${rows||'<tr><td colspan="10" class="hr-empty">Шүүлтэд тохирох ажилтан алга.</td></tr>'}</tbody></table></div>
  </section>${hrEmployeeDialog(d,selected)}`;
};

async function openHrEmployeeDialog(id=null){
  state.hrRegistry.selectedId=id;state.hrRegistry.file=null;state.hrRegistry.attachments=[];
  renderAdministration("hr");
  queueMicrotask(()=>document.getElementById("hrEmployeeDialog")?.showModal());
  if(id){try{[state.hrRegistry.file,{items:state.hrRegistry.attachments}]=await Promise.all([api(`/api/hr/employees/${id}/file`),api(`/api/attachments/entity/employees/${id}`)]);renderAdministration("hr");queueMicrotask(()=>document.getElementById("hrEmployeeDialog")?.showModal())}catch(error){toast(error.message,true)}}
}
document.addEventListener("click",event=>{
  const add=event.target.closest("[data-hr-add]"),edit=event.target.closest("[data-hr-edit]"),close=event.target.closest("[data-hr-close]");
  if(add)openHrEmployeeDialog();
  if(edit)openHrEmployeeDialog(edit.dataset.hrEdit);
  if(close)document.getElementById("hrEmployeeDialog")?.close();
});
document.addEventListener("input",event=>{
  if(!event.target.matches("[data-hr-search]"))return;
  state.hrRegistry.search=event.target.value;
  const value=event.target.value;renderAdministration("hr");
  const input=document.querySelector("[data-hr-search]");if(input){input.focus();input.value=value;input.setSelectionRange(value.length,value.length)}
});
document.addEventListener("change",event=>{
  if(event.target.matches("[data-hr-department]")){state.hrRegistry.department=event.target.value;renderAdministration("hr")}
  if(event.target.matches("[data-hr-status]")){state.hrRegistry.status=event.target.value;renderAdministration("hr")}
});
document.addEventListener("submit",async event=>{
  const form=event.target;
  const lifecycleForms=["hrContractForm","hrCompensationForm","hrLifecycleForm","hrDocumentForm","hrPositionDescriptionForm"];
  if(form.id!=="hrEmployeeForm"&&!lifecycleForms.includes(form.id))return;event.preventDefault();
  const values=Object.fromEntries(new FormData(form));
  const employeeId=form.dataset.employeeId;
  Object.keys(values).forEach(key=>{if(values[key]==="")delete values[key]});
  try{
    if(lifecycleForms.includes(form.id)){
      let endpoint="";
      if(form.id==="hrContractForm")endpoint=`/api/hr/employees/${employeeId}/contracts`;
      if(form.id==="hrCompensationForm"){endpoint=`/api/hr/employees/${employeeId}/compensation`;values.approved=Boolean(values.approved);values.allowances={}}
      if(form.id==="hrLifecycleForm")endpoint=`/api/hr/employees/${employeeId}/lifecycle`;
      if(form.id==="hrDocumentForm")endpoint=`/api/hr/employees/${employeeId}/documents`;
      if(form.id==="hrPositionDescriptionForm"){endpoint=`/api/hr/positions/${form.dataset.positionId}/descriptions`;values.duties=hrLines(values.duties);values.responsibilities=hrLines(values.responsibilities);values.requirements=hrLines(values.requirements)}
      await api(endpoint,{method:"POST",body:JSON.stringify(values)});
      state.hrRegistry.file=await api(`/api/hr/employees/${employeeId}/file`);renderAdministration("hr");
      queueMicrotask(()=>document.getElementById("hrEmployeeDialog")?.showModal());toast("Түүхэн бүртгэл хадгалагдлаа");return;
    }
    await api(employeeId?`/api/hr/employees/${employeeId}`:"/api/hr/employees",{method:employeeId?"PATCH":"POST",body:JSON.stringify(values)});
    document.getElementById("hrEmployeeDialog")?.close();state.hrRegistry.selectedId=null;
    await reloadAdministration("hr",employeeId?"Ажилтны мэдээлэл хадгалагдлаа":"Ажилтан бүртгэгдлээ");
  }catch(error){toast(error.message,true)}
});

// Core HR is one workspace. Employee master data remains the source of truth;
// operational tabs only reference employee IDs and never create duplicate people.
const hrEmployeeMasterView=hrAdministration;
const hrTabNames={employees:"Ажилтны бүртгэл",smartImport:"Ухаалаг импорт",leave:"Чөлөө, амралт",attendance:"Ирцийн залруулга",schedule:"Хуваарь",skills:"Ур чадвар, сургалт",performance:"Гүйцэтгэл",transition:"Ажилд авах / гарах",reports:"Хяналт, тайлан"};
function hrWorkspaceTabs(){return `<nav class="hr-workspace-tabs">${Object.entries(hrTabNames).map(([key,label])=>`<button type="button" data-hr-tab="${key}" class="${state.hrRegistry.tab===key?"active":""}">${label}</button>`).join("")}</nav>`}
function hrEmployeeOptions(d,selected=""){return `<option value="">Ажилтан сонгоно уу</option>${d.employees.map(x=>`<option value="${x.id}" ${x.id===selected?"selected":""}>${esc(x.full_name)} · ${esc(x.position_title||"Албан тушаалгүй")}</option>`).join("")}`}
function hrOperationsHeader(title,description){return `${hrWorkspaceTabs()}${header("ХҮНИЙ НӨӨЦИЙН УДИРДЛАГА",title,description)}`}
function hrStatusBadge(status){const names={pending:"Хүлээгдэж буй",approved:"Баталсан",rejected:"Татгалзсан",cancelled:"Цуцалсан",planned:"Төлөвлөсөн",in_progress:"Хэрэгжиж буй",completed:"Дууссан",draft:"Ноорог",submitted:"Илгээсэн",acknowledged:"Танилцсан",closed:"Хаасан",open:"Нээлттэй"};return `<span class="hr-tag ${status}">${esc(names[status]||status)}</span>`}

function hrLeaveView(d,o){const rows=o.leaveRequests.map(x=>`<tr><td><strong>${esc(x.employee_name)}</strong></td><td>${esc(x.leave_type)}</td><td>${adminDate(x.starts_on)} — ${adminDate(x.ends_on)}</td><td>${esc(x.requested_days)} өдөр</td><td>${hrStatusBadge(x.status)}</td><td>${x.status==="pending"&&o.canApproveLeave?`<button data-hr-leave-decision="${x.id}" data-decision="approved" class="hr-edit">Батлах</button> <button data-hr-leave-decision="${x.id}" data-decision="rejected" class="hr-edit danger">Татгалзах</button>`:"—"}</td></tr>`).join("");return `${hrOperationsHeader("Чөлөө, амралтын удирдлага","Хүсэлтээс шийдвэр хүртэлх түүхийг өөрчлөх боломжгүй үйл явдлаар хадгална.")}<form id="hrLeaveForm" class="admin-form"><h2>Чөлөөний хүсэлт бүртгэх</h2><div class="admin-fields"><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Төрөл<select name="leaveType"><option value="annual">Ээлжийн амралт</option><option value="sick">Өвчтэй</option><option value="unpaid">Цалингүй чөлөө</option><option value="family">Гэр бүлийн чөлөө</option><option value="training">Сургалт</option><option value="other">Бусад</option></select></label><label>Эхлэх<input name="startsOn" type="date" required></label><label>Дуусах<input name="endsOn" type="date" required></label><label>Өдрийн тоо<input name="requestedDays" type="number" min="0.5" step="0.5" required></label><label>Шалтгаан<input name="reason" maxlength="2000"></label></div><button class="primary">Хүсэлт бүртгэх</button></form><section class="admin-panel"><div class="panel-head"><h2>Хүсэлтийн түүх</h2><span>${o.leaveRequests.length}</span></div><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Төрөл</th><th>Хугацаа</th><th>Өдөр</th><th>Төлөв</th><th>Шийдвэр</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Хүсэлт алга.</td></tr>'}</tbody></table></div></section>`}

function hrScheduleView(d,o){const rows=o.scheduleAssignments.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.schedule_name)}</td><td>${adminDate(x.effective_from)} — ${adminDate(x.effective_to)}</td></tr>`).join("");return `${hrOperationsHeader("Ажлын хуваарь","Ажилтны хуваарийг хүчинтэй хугацаатайгаар оноож, өмнөх түүхийг хадгална.")}<div class="admin-two"><form id="hrScheduleForm" class="admin-form"><h2>Хуваарийн загвар</h2><div class="admin-fields"><label>Код<input name="code" required></label><label>Нэр<input name="name" required></label><label>Эхлэх цаг<input name="startTime" type="time" value="09:00" required></label><label>Дуусах цаг<input name="endTime" type="time" value="18:00" required></label></div><button class="primary">Загвар үүсгэх</button></form><form id="hrScheduleAssignmentForm" class="admin-form"><h2>Ажилтанд оноох</h2><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Хуваарь<select name="scheduleId" required><option value="">Хуваарь сонгоно уу</option>${o.schedules.map(x=>`<option value="${x.id}">${esc(x.code)} · ${esc(x.name)}</option>`).join("")}</select></label><div class="admin-fields"><label>Эхлэх<input name="effectiveFrom" type="date" required></label><label>Дуусах<input name="effectiveTo" type="date"></label></div><button class="secondary">Хуваарь оноох</button></form></div><section class="admin-panel"><div class="panel-head"><h2>Оноолтын түүх</h2></div><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Хуваарь</th><th>Хүчинтэй хугацаа</th></tr></thead><tbody>${rows||'<tr><td colspan="3">Хуваарь оноогоогүй.</td></tr>'}</tbody></table></div></section>`}

function hrSkillsView(d,o){const skills=o.skills.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.name)}</td><td>${x.proficiency_level}/5</td><td>${esc(x.certificate_no||"—")}</td><td>${adminDate(x.expires_at)}</td></tr>`).join("");const training=o.training.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.title)}</td><td>${esc(x.provider||"—")}</td><td>${hrStatusBadge(x.status)}</td><td>${adminDate(x.completed_on)}</td></tr>`).join("");return `${hrOperationsHeader("Ур чадвар ба хөгжил","Ур чадвар нь нэвтрэх эрхээс бус ажилтны master бүртгэлээс хамаарна.")}<div class="admin-two"><form id="hrSkillCatalogForm" class="admin-form"><h2>Ур чадварын сан</h2><div class="admin-fields"><label>Код<input name="code" required></label><label>Нэр<input name="name" required></label><label>Ангилал<input name="category" value="general" required></label><label class="admin-check"><input type="checkbox" name="certificationRequired"> Сертификат шаардана</label></div><button class="primary">Санд нэмэх</button></form><form id="hrEmployeeSkillForm" class="admin-form"><h2>Ажилтны ур чадвар</h2><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Ур чадвар<select name="skillId" required><option value="">Сонгоно уу</option>${o.organizationSkills.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></label><div class="admin-fields"><label>Түвшин (1–5)<input name="proficiencyLevel" type="number" min="1" max="5" value="1" required></label><label>Үнэмлэхийн №<input name="certificateNo"></label><label>Олгосон<input name="issuedAt" type="date"></label><label>Дуусах<input name="expiresAt" type="date"></label></div><button class="secondary">Баталгаажуулах</button></form></div><form id="hrTrainingForm" class="admin-form"><h2>Сургалт бүртгэх</h2><div class="admin-fields"><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Сургалт<input name="title" required></label><label>Байгууллага / багш<input name="provider"></label><label>Эхлэх<input name="startsOn" type="date"></label><label>Дууссан<input name="completedOn" type="date"></label><label>Төлөв<select name="status"><option value="planned">Төлөвлөсөн</option><option value="in_progress">Хэрэгжиж буй</option><option value="completed">Дууссан</option><option value="cancelled">Цуцалсан</option></select></label></div><button class="primary">Сургалт хадгалах</button></form><section class="admin-panel"><h2>Ур чадвар</h2><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Ур чадвар</th><th>Түвшин</th><th>Үнэмлэх</th><th>Дуусах</th></tr></thead><tbody>${skills||'<tr><td colspan="5">Бүртгэл алга.</td></tr>'}</tbody></table></div><h2>Сургалтын түүх</h2><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Сургалт</th><th>Зохион байгуулагч</th><th>Төлөв</th><th>Дууссан</th></tr></thead><tbody>${training||'<tr><td colspan="5">Бүртгэл алга.</td></tr>'}</tbody></table></div></section>`}

function hrPerformanceView(d,o){const reviewers=d.employees.filter(x=>x.user_id).map(x=>`<option value="${x.user_id}">${esc(x.full_name)}</option>`).join("");const rows=o.performanceReviews.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${adminDate(x.period_start)} — ${adminDate(x.period_end)}</td><td>${x.score??"—"}</td><td>${hrStatusBadge(x.status)}</td><td>${esc(x.reviewer_name)}</td></tr>`).join("");return `${hrOperationsHeader("Гүйцэтгэл ба үнэлгээ","Зорилго, үнэлгээ, баталгаажуулалтыг хугацаа болон хариуцагчтай хадгална.")}${o.canManagePerformance?`<form id="hrPerformanceForm" class="admin-form"><div class="admin-fields"><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Үнэлэгч<select name="reviewerUserId" required><option value="">Сонгоно уу</option>${reviewers}</select></label><label>Эхлэх<input name="periodStart" type="date" required></label><label>Дуусах<input name="periodEnd" type="date" required></label><label>Оноо<input name="score" type="number" min="0" max="100"></label><label>Төлөв<select name="status"><option value="draft">Ноорог</option><option value="submitted">Илгээсэн</option><option value="closed">Хаасан</option></select></label></div><label>Зорилгууд (мөр бүрээр)<textarea name="goals"></textarea></label><label>Дүгнэлт<textarea name="summary"></textarea></label><button class="primary">Үнэлгээ хадгалах</button></form>`:'<section class="admin-panel"><p>Гүйцэтгэлийн нууц мэдээлэл харах эрхгүй.</p></section>'}<section class="admin-panel"><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Хугацаа</th><th>Оноо</th><th>Төлөв</th><th>Үнэлэгч</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Үнэлгээ алга.</td></tr>'}</tbody></table></div></section>`}

function hrTransitionView(d,o){const rows=o.transitionChecklists.map(x=>`<article class="hr-checklist"><h3>${esc(x.employee_name)} · ${x.checklist_type==="onboarding"?"Ажилд авах":"Ажлаас гарах"}</h3><span>${adminDate(x.effective_date)} · ${hrStatusBadge(x.status)}</span>${x.items.map(i=>`<label><input type="checkbox" data-hr-checklist-item="${i.id}" ${i.completedAt?"checked":""}> ${esc(i.title)}</label>`).join("")}</article>`).join("");return `${hrOperationsHeader("Ажилд авах ба ажлаас гарах","Эрх, эд хөрөнгө, баримт, танилцуулга болон хүлээлцэх ажлыг checklist-ээр хянана.")}<form id="hrChecklistForm" class="admin-form"><div class="admin-fields"><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Урсгал<select name="checklistType"><option value="onboarding">Ажилд авах</option><option value="offboarding">Ажлаас гарах</option></select></label><label>Хүчинтэй огноо<input name="effectiveDate" type="date" required></label></div><label>Ажлууд (мөр бүрээр)<textarea name="items" required>Гэрээ ба тушаал баталгаажуулах&#10;Нэвтрэх эрх тохируулах&#10;Эд хөрөнгө хүлээлцэх&#10;ХАБЭА танилцуулга&#10;Албан тушаалын тодорхойлолт танилцуулах</textarea></label><button class="primary">Checklist үүсгэх</button></form><section class="hr-checklist-grid">${rows||'<article class="admin-panel">Checklist алга.</article>'}</section>`}

function hrCorrectionsView(d,o){const rows=o.attendanceCorrections.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${adminDate(x.attendance_date)}</td><td>${esc(x.reason)}</td><td>${hrStatusBadge(x.status)}</td><td>${x.status==="pending"&&o.canApproveLeave?`<button data-hr-correction-decision="${x.id}" data-decision="approved" class="hr-edit">Батлах</button> <button data-hr-correction-decision="${x.id}" data-decision="rejected" class="hr-edit danger">Татгалзах</button>`:"—"}</td></tr>`).join("");return `${hrOperationsHeader("Ирцийн залруулга","Ирц устгахгүй. Алдааг хүсэлт, шийдвэр, хэрэгжүүлсэн түүхтэйгээр залруулна.")}<form id="hrCorrectionForm" class="admin-form"><div class="admin-fields"><label>Ажилтан<select name="employeeId" required>${hrEmployeeOptions(d)}</select></label><label>Огноо<input name="attendanceDate" type="date" required></label><label>Төлөв<select name="status"><option value="worked">Ажилласан</option><option value="absent">Тасалсан</option><option value="leave">Чөлөөтэй</option><option value="sick">Өвчтэй</option><option value="vacation">Амралт</option><option value="late">Хоцорсон</option></select></label><label>Ажилласан цаг<input name="workHours" type="number" min="0" max="8" value="8"></label><label>Чөлөөний цаг<input name="leaveHours" type="number" min="0" max="8" value="0"></label><label>Илүү цаг<input name="overtimeHours" type="number" min="0" max="16" value="0"></label><label>Хоцорсон минут<input name="lateMinutes" type="number" min="0" value="0"></label><label>Шалтгаан<input name="reason" required></label></div><button class="primary">Залруулах хүсэлт илгээх</button></form><section class="admin-panel"><div class="admin-table-wrap"><table><thead><tr><th>Ажилтан</th><th>Огноо</th><th>Шалтгаан</th><th>Төлөв</th><th>Шийдвэр</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Хүсэлт алга.</td></tr>'}</tbody></table></div></section>`}

function hrReportsView(d,o){return `${hrOperationsHeader("Хяналт ба тайлан","Хүний нөөцийн анхаарах хугацаа, дутуу бүртгэл, батлах хүсэлтийг нэг дор харна.")}${administrationCards([["Нийт ажилтан",d.summary.total_employees],["Профайл дутуу",d.summary.incomplete_profiles,"warn"],["Хүлээгдэж буй чөлөө",o.leaveRequests.filter(x=>x.status==="pending").length],["Ирцийн залруулга",o.attendanceCorrections.filter(x=>x.status==="pending").length]])}<section class="admin-panel"><div class="panel-head"><h2>60 хоногт анхаарах зүйлс</h2><span>${o.alerts.length}</span></div><div class="admin-table-wrap"><table><thead><tr><th>Төрөл</th><th>Ажилтан</th><th>Хугацаа</th><th>Лавлагаа</th></tr></thead><tbody>${o.alerts.map(x=>`<tr><td>${x.alert_type==="contract_expiry"?"Гэрээ":"Үнэмлэх"}</td><td>${esc(x.full_name)}</td><td>${adminDate(x.due_date)}</td><td>${esc(x.reference||"—")}</td></tr>`).join("")||'<tr><td colspan="4">Анхааруулга алга.</td></tr>'}</tbody></table></div></section>`}

const smartImportFields={fullName:"Овог нэр *",employeeNo:"Ажилтны дугаар",departmentName:"Хэлтэс / нэгж",positionTitle:"Албан тушаал",phone:"Утас",personalEmail:"И-мэйл",hireDate:"Ажилд орсон огноо",gender:"Хүйс",workCondition:"Ажлын нөхцөл",education:"Боловсрол",contractType:"Гэрээний төрөл",contractNo:"Гэрээний дугаар",contractEnd:"Гэрээ дуусах"};
const smartImportSourceLabels={"Employee ID":"Ажилтны дугаар","Employee Name":"Овог нэр",Department:"Хэлтэс / нэгж",Position:"Албан тушаал","Branch/Location":"Салбар / байршил","Reports To":"Шууд удирдлага","Employment Type":"Ажил эрхлэлтийн төрөл",Status:"Төлөв","Hire Date":"Ажилд орсон огноо"};
const smartImportValueLabels={Executive:"Удирдлага","Finance & Accounting":"Санхүү ба нягтлан бодох бүртгэл","HR & Administration":"Хүний нөөц ба захиргаа",Sales:"Борлуулалт",Procurement:"Худалдан авалт","Warehouse & Inventory":"Агуулах ба бараа материал",Logistics:"Ложистик","Customer Service & E-commerce":"Харилцагчийн үйлчилгээ ба цахим худалдаа","IT & Systems":"Мэдээллийн технологи ба систем","Full-time":"Бүтэн цагийн",Active:"Идэвхтэй",Central:"Төв",East:"Зүүн",North:"Хойд",West:"Баруун"};
function smartImportSourceLabel(value){return smartImportSourceLabels[value]||value}
function smartImportDisplayValue(value){return smartImportValueLabels[value]||value}
function smartImportWarningLabel(value){return /fetch failed/i.test(String(value||""))?"Хиймэл оюуны санал авах үед сүлжээний алдаа гарлаа. Стандарт дүрмээр шинжилсэн.":value}
function smartImportSheetLabel(value){return value==="Employee_Master"?"Ажилтны үндсэн мэдээлэл":value}
const smartImportStatus={analyzing:"Шинжилж байна",needs_review:"Хүний хяналт хүлээж байна",approved:"Баталсан",importing:"Үндсэн санд оруулж байна",completed:"Дууссан",failed:"Алдаатай"};
async function loadSmartImports(){try{const result=await api("/api/hr/smart-imports");state.hrRegistry.imports=result.items;if(state.view==="hr"&&state.hrRegistry.tab==="smartImport")renderAdministration("hr")}catch(error){toast(error.message,true)}}
async function loadSmartImportJob(id){try{const result=await api(`/api/hr/smart-imports/${id}`);state.hrRegistry.importJob=result.item;renderAdministration("hr")}catch(error){toast(error.message,true)}}
function smartImportMapping(job){return `<form id="smartImportMappingForm" class="admin-form smart-import-mapping"><div class="panel-head"><div><h2>Баганын утгыг тохируулах</h2><p>Хиймэл оюун болон стандарт дүрмийн саналыг хүн шалгаж батална.</p></div><button class="secondary">Тохиргоог дахин шалгах</button></div><div class="smart-import-map-grid">${job.source_columns.map(source=>{const confidence=job.mapping_confidence?.[source];return `<label><span>${esc(smartImportSourceLabel(source))}</span><select data-import-source="${esc(source)}"><option value="">Импортлохгүй</option>${Object.entries(smartImportFields).map(([value,label])=>`<option value="${value}" ${job.proposed_mapping?.[source]===value?"selected":""}>${label}</option>`).join("")}</select><small>${confidence?`${Math.round(Number(confidence.score||0)*100)}% · ${esc(confidence.reason||"")}`:"Гараар тохируулна"}</small></label>`}).join("")}</div></form>`}
function smartImportPreview(job){const rows=(job.rows||[]).map(row=>`<tr><td>${row.row_number}</td><td><strong>${esc(row.normalized_data?.fullName||"—")}</strong><small>${esc(row.normalized_data?.employeeNo||"")}</small></td><td>${esc(smartImportDisplayValue(row.normalized_data?.departmentName)||"—")}</td><td>${esc(smartImportDisplayValue(row.normalized_data?.positionTitle)||"—")}</td><td><span class="smart-import-row ${row.status}">${row.status==="ready"?"Бэлэн":row.status==="warning"?"Анхааруулгатай":row.status==="imported"?"Импортолсон":"Алдаатай"}</span><small>${esc([...(row.validation?.errors||[]),...(row.validation?.warnings||[])].join(" · "))}</small></td></tr>`).join("");return `<section class="admin-panel"><div class="panel-head"><h2>Мөрийн урьдчилсан хяналт</h2><span>${job.preview_limited?"Эхний 200 мөр":"Бүх мөр"}</span></div><div class="admin-table-wrap"><table class="smart-import-table"><thead><tr><th>Мөр</th><th>Ажилтан</th><th>Хэлтэс</th><th>Албан тушаал</th><th>Шалгалт</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function smartImportJobView(job){const s=job.summary||{},canApprove=job.status==="needs_review"&&Number(s.errors||0)===0,canCommit=job.status==="approved";return `<section class="smart-import-job"><div class="smart-import-job-head"><div><small>${esc(job.original_filename)}${s.sourceSheet?` · Хуудас: ${esc(smartImportSheetLabel(s.sourceSheet))}`:""}</small><h2>${smartImportStatus[job.status]||esc(job.status)}</h2><p>${job.analysis_mode==="ai_assisted"?"OVERVA хиймэл оюун багана танихад тусалсан":"Стандарт дүрмээр багана таньсан"}. Үндсэн санд хараахан бичээгүй.</p></div><div class="smart-import-actions">${canApprove?`<button class="secondary" data-import-approve="${job.id}">Хяналтыг батлах</button>`:""}${canCommit?`<button class="primary" data-import-commit="${job.id}">Үндсэн санд импортлох</button>`:""}</div></div>${administrationCards([["Нийт мөр",s.total],["Бэлэн",s.ready],["Анхааруулга",s.warnings,"warn"],["Алдаа",s.errors,"warn"],["Шинэ хэлтэс",s.newDepartments?.length||0],["Шинэ албан тушаал",s.newPositions?.length||0]])}${s.compatibilityNormalized?'<p class="smart-import-notice">Excel файлын дотоод бүтцийг нийцтэй горимоор амжилттай уншлаа.</p>':""}${(s.aiWarnings||[]).map(w=>`<p class="smart-import-notice">${esc(smartImportWarningLabel(w))}</p>`).join("")}${job.status==="needs_review"?smartImportMapping(job):""}${smartImportPreview(job)}<p class="smart-import-safety">Зөвхөн ажилтны үндсэн бүртгэл үүснэ. Нэвтрэх нэр, нууц үг болон хэрэглэгчийн эрх автоматаар үүсэхгүй.</p></section>`}
function hrSmartImportView(){if(state.hrRegistry.imports===null){queueMicrotask(loadSmartImports);return `${hrOperationsHeader("Ухаалаг импорт","Excel болон CSV өгөгдлийг үндсэн санд бичихээс өмнө хиймэл оюун, дүрэм болон хүний хяналтаар шалгана.")}<section class="admin-panel smart-import-loading">Импортын түүхийг ачаалж байна...</section>`}const recent=(state.hrRegistry.imports||[]).map(item=>`<button type="button" data-import-open="${item.id}"><strong>${esc(item.original_filename)}</strong><span>${smartImportStatus[item.status]||esc(item.status)} · ${adminDate(item.created_at)}</span></button>`).join("");return `${hrOperationsHeader("Ухаалаг импорт","Олон ажилтны мэдээллийг хурдан оруулах боловч хиймэл оюунд шууд шийдвэр гаргах, үндсэн санд бичих эрх өгөхгүй.")}<div class="smart-import-layout"><div><form id="smartImportUploadForm" class="admin-form smart-import-upload"><h2>1. Файл оруулах</h2><p>.xlsx эсвэл .csv · 10 МБ хүртэл · 5,000 мөр хүртэл</p><label>Ажилтны мэдээллийн файл<input name="file" type="file" accept=".xlsx,.csv" required></label><button class="primary">Шинжилж, түр хадгалалтад оруулах</button><small>Файлын хэш, баганын тохиргоо, баталгаа болон импортын үйлдэл аудитын түүхэд хадгалагдана.</small></form><section class="admin-panel smart-import-recent"><div class="panel-head"><h2>Сүүлийн импорт</h2></div>${recent||"<p>Импортын түүх алга.</p>"}</section></div><div>${state.hrRegistry.importJob?smartImportJobView(state.hrRegistry.importJob):'<section class="admin-panel smart-import-empty"><h2>Импортын аюулгүй урсгал</h2><ol><li>Файл түр хадгалалтад орно</li><li>Хиймэл оюун баганын утгыг санал болгоно</li><li>Давхардал, хэлбэр болон заавал бөглөх талбарыг шалгана</li><li>Хүн баганын тохиргоо болон мөрүүдийг батална</li><li>Нэг үйлдлээр ажилтны үндсэн бүртгэлд оруулна</li></ol></section>'}</div></div>`}

hrAdministration=function(d){const o=d.operations||{leaveRequests:[],attendanceCorrections:[],schedules:[],scheduleAssignments:[],organizationSkills:[],skills:[],training:[],performanceReviews:[],transitionChecklists:[],alerts:[]};const tab=state.hrRegistry.tab;const views={smartImport:hrSmartImportView,leave:hrLeaveView,attendance:hrCorrectionsView,schedule:hrScheduleView,skills:hrSkillsView,performance:hrPerformanceView,transition:hrTransitionView,reports:hrReportsView};return tab==="employees"?`${hrWorkspaceTabs()}${hrEmployeeMasterView(d)}`:(views[tab]||hrReportsView)(d,o)};

document.addEventListener("click",async event=>{
  const tab=event.target.closest("[data-hr-tab]");if(tab){state.hrRegistry.tab=tab.dataset.hrTab;renderAdministration("hr");return}
  const importOpen=event.target.closest("[data-import-open]"),importApprove=event.target.closest("[data-import-approve]"),importCommit=event.target.closest("[data-import-commit]");
  const leave=event.target.closest("[data-hr-leave-decision]"),correction=event.target.closest("[data-hr-correction-decision]");
  const checklist=event.target.closest("[data-hr-checklist-item]");
  const download=event.target.closest("[data-hr-file-download]");
  try{
    if(importOpen){await loadSmartImportJob(importOpen.dataset.importOpen);return}
    if(importApprove){const result=await api(`/api/hr/smart-imports/${importApprove.dataset.importApprove}/approve`,{method:"POST"});state.hrRegistry.importJob=result.item;await loadSmartImports();toast("Импортын хяналтыг баталлаа");return}
    if(importCommit){if(!confirm("Баталсан мөрүүдийг ажилтны үндсэн санд оруулах уу?"))return;const result=await api(`/api/hr/smart-imports/${importCommit.dataset.importCommit}/commit`,{method:"POST"});state.hrRegistry.importJob=result.item;state.administration.hr=null;await loadAdministration("hr");await loadSmartImports();toast("Ажилтны үндсэн бүртгэл амжилттай импортлогдлоо");return}
    if(download){const response=await fetch(`/api/attachments/file/${download.dataset.hrFileDownload}`,{headers:{authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error("Файл татаж чадсангүй");const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="employee-file";a.click();URL.revokeObjectURL(url)}
    if(leave){await api(`/api/hr/leave-requests/${leave.dataset.hrLeaveDecision}/decision`,{method:"PATCH",body:JSON.stringify({decision:leave.dataset.decision,note:""})});await reloadAdministration("hr","Чөлөөний хүсэлт шийдвэрлэгдлээ")}
    if(correction){await api(`/api/hr/attendance-corrections/${correction.dataset.hrCorrectionDecision}/decision`,{method:"PATCH",body:JSON.stringify({decision:correction.dataset.decision,note:""})});await reloadAdministration("hr","Ирцийн залруулга шийдвэрлэгдлээ")}
    if(checklist){await api(`/api/hr/checklist-items/${checklist.dataset.hrChecklistItem}`,{method:"PATCH",body:JSON.stringify({completed:checklist.checked,note:""})});await reloadAdministration("hr","Checklist шинэчлэгдлээ")}
  }catch(error){toast(error.message,true)}
});

document.addEventListener("submit",async event=>{
  const form=event.target;
  if(form.id==="smartImportUploadForm"){
    event.preventDefault();const button=form.querySelector("button");button.disabled=true;button.textContent="AI шинжилж байна...";
    try{const response=await fetch("/api/hr/smart-imports",{method:"POST",headers:{authorization:`Bearer ${state.token}`},body:new FormData(form)});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Файл шинжилж чадсангүй");state.hrRegistry.importJob=body.item;await loadSmartImports();toast("Файлыг staging-д оруулж шалгалаа")}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent="Шинжилж, staging-д оруулах"}return;
  }
  if(form.id==="smartImportMappingForm"){
    event.preventDefault();const mapping={};form.querySelectorAll("[data-import-source]").forEach(select=>{if(select.value)mapping[select.dataset.importSource]=select.value});
    try{const result=await api(`/api/hr/smart-imports/${state.hrRegistry.importJob.id}/mapping`,{method:"PATCH",body:JSON.stringify({mapping})});state.hrRegistry.importJob=result.item;renderAdministration("hr");toast("Mapping болон мөрийн шалгалтыг шинэчиллээ")}catch(error){toast(error.message,true)}return;
  }
});

document.addEventListener("submit",async event=>{
  if(event.target.id==="hrAttachmentForm"){
    event.preventDefault();const form=event.target,data=new FormData(form);
    try{const response=await fetch(`/api/attachments/entity/employees/${form.dataset.employeeId}`,{method:"POST",headers:{authorization:`Bearer ${state.token}`},body:data});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Файл хавсаргаж чадсангүй");({items:state.hrRegistry.attachments}=await api(`/api/attachments/entity/employees/${form.dataset.employeeId}`));renderAdministration("hr");queueMicrotask(()=>document.getElementById("hrEmployeeDialog")?.showModal());toast("Файл хавсаргалаа")}catch(error){toast(error.message,true)}return;
  }
  const ids=new Set(["hrLeaveForm","hrCorrectionForm","hrScheduleForm","hrScheduleAssignmentForm","hrSkillCatalogForm","hrEmployeeSkillForm","hrTrainingForm","hrPerformanceForm","hrChecklistForm"]);
  if(!ids.has(event.target.id))return;event.preventDefault();const form=event.target,v=Object.fromEntries(new FormData(form));let endpoint="",method="POST";
  Object.keys(v).forEach(k=>{if(v[k]==="")delete v[k]});
  if(form.id==="hrLeaveForm")endpoint="/api/hr/leave-requests";
  if(form.id==="hrCorrectionForm"){endpoint="/api/hr/attendance-corrections";v.requestedValues={status:v.status,workHours:v.workHours,leaveHours:v.leaveHours,overtimeHours:v.overtimeHours,lateMinutes:v.lateMinutes,note:""};["status","workHours","leaveHours","overtimeHours","lateMinutes"].forEach(k=>delete v[k])}
  if(form.id==="hrScheduleForm"){endpoint="/api/hr/schedules";v.weeklyPattern={mon:{start:v.startTime,end:v.endTime},tue:{start:v.startTime,end:v.endTime},wed:{start:v.startTime,end:v.endTime},thu:{start:v.startTime,end:v.endTime},fri:{start:v.startTime,end:v.endTime}};delete v.startTime;delete v.endTime}
  if(form.id==="hrScheduleAssignmentForm"){endpoint=`/api/hr/employees/${v.employeeId}/schedules`;delete v.employeeId}
  if(form.id==="hrSkillCatalogForm"){endpoint="/api/hr/skills-catalog";v.certificationRequired=new FormData(form).has("certificationRequired")}
  if(form.id==="hrEmployeeSkillForm"){endpoint=`/api/hr/employees/${v.employeeId}/skills`;method="PUT";delete v.employeeId}
  if(form.id==="hrTrainingForm"){endpoint=`/api/hr/employees/${v.employeeId}/training`;delete v.employeeId}
  if(form.id==="hrPerformanceForm"){endpoint=`/api/hr/employees/${v.employeeId}/performance`;delete v.employeeId;v.goals=hrLines(v.goals)}
  if(form.id==="hrChecklistForm"){endpoint=`/api/hr/employees/${v.employeeId}/checklists`;delete v.employeeId;v.items=hrLines(v.items).map((title,index)=>({code:`item-${index+1}`,title}))}
  try{await api(endpoint,{method,body:JSON.stringify(v)});form.reset();await reloadAdministration("hr","Хүний нөөцийн бүртгэл хадгалагдлаа")}catch(error){toast(error.message,true)}
});
